add_filter( 'sidebars_widgets', 'perfectpixel_hide_sidebar_on_cart_checkout' );

function perfectpixel_hide_sidebar_on_cart_checkout( $sidebars ) {
	if ( is_admin() || ! function_exists( 'is_cart' ) || ! did_action( 'wp' ) ) {
		return $sidebars; // Conditionals are only reliable after the main query.
	}
	$hide = is_cart() || is_checkout() || ( 'yes' === '{{hide_sidebar_on_account}}' && is_account_page() );
	$id   = sanitize_key( '{{hidden_sidebar_id}}' );
	if ( $hide && isset( $sidebars[ $id ] ) ) {
		$sidebars[ $id ] = array();
	}
	return $sidebars;
}
